public class Solution{public bool IsNumber(string s){bool num=false,dot=false,exp=false,after=true;for(int i=0;i<s.Length;i++){char c=s[i];if(char.IsDigit(c)){num=true;after=true;}else if(c=='.'){if(dot||exp)return false;dot=true;}else if(c=='e'||c=='E'){if(exp||!num)return false;exp=true;after=false;}else if(c=='+'||c=='-'){if(i>0&&s[i-1]!='e'&&s[i-1]!='E')return false;}else return false;}return num&&after;}}
